def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    # Helpers inline (built from history each call)
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    my_last = my[-1]
    op_last = op[-1]
    opp_def = op.count('D')
    my_def = my.count('D')
    opp_c = n - opp_def
    my_c = n - my_def
    remaining = 100 - n

    # 1. Near-perfect defector detection: very high defection rate.
    if n >= 8 and opp_def * 5 >= n * 4:
        # Wait for very strong evidence, then defect permanently.
        return 'D'

    # 2. Endgame exploitation: when few rounds remain, defect if opponent
    #    has shown a cooperative tendency (higher chance of DC payoff).
    if remaining <= 12:
        if opp_c * 3 >= n * 2:
            return 'D'
        if opp_def * 3 >= n * 2:
            return 'D'
        # Otherwise fall through to normal logic

    # 3. If opponent never defected at all, cooperate fully early,
    #    exploit on the very last rounds.
    if opp_def == 0:
        if remaining <= 5:
            return 'D'
        return 'C'

    # 4. If opponent is mostly cooperative (few defections), use mostly
    #    tit-for-tat with quick forgiveness and occasional exploitation.
    if opp_def * 4 <= n:
        if op_last == 'D':
            # Forgive if their defection seems isolated.
            if n >= 3 and op[-2] == 'C' and op[-3] == 'C':
                return 'C'
            # Otherwise retaliate once.
            return 'D'
        # Opponent cooperated. Occasional probing defection to grab DC,
        # but not too often to avoid punishment spirals.
        if n >= 10 and remaining > 12:
            if my_last == 'C' and opp_c >= 8 and rng.random() < 0.12:
                return 'D'
        return 'C'

    # 5. Detect likely TFT-like opponent: they mostly mirror our previous move.
    if n >= 6:
        matches = 0
        considered = 0
        # Off-by-one: op[i] vs my[i-1]
        for i in range(1, n):
            considered += 1
            if op[i] == my[i - 1]:
                matches += 1
        if considered >= 5 and matches * 5 >= considered * 4:
            # Opponent mirrors us. Cooperate to sustain mutual cooperation,
            # but at the very end defect to exploit the last step.
            if remaining <= 2:
                return 'D'
            return 'C'

    # 6. Moderate defector: retaliate proportionally but avoid endless DD.
    if opp_def * 2 >= n:
        if op_last == 'D':
            return 'D'
        # Opponent cooperated once — defect or cooperate?
        # If recent op defection streak is long, defect. If they've just
        # started cooperating, cooperate to encourage more.
        recent = op[-5:]
        rdef = recent.count('D')
        if rdef >= 3:
            return 'D'
        if n >= 4 and rdef <= 1 and rng.random() < 0.5:
            return 'C'
        return 'D'

    # 7. Middle-ground. Use tit-for-tat with a bit of forgiveness.
    if op_last == 'D':
        # Retaliate most of the time, but forgive after long cooperation runs.
        if n >= 4 and op[-2] == 'C' and op[-3] == 'C' and rng.random() < 0.4:
            return 'C'
        return 'D'
    else:
        # Opponent cooperated. Cooperate, but occasionally probe.
        if n >= 10 and remaining > 12 and my_c > n * 0.75:
            if rng.random() < 0.06:
                return 'D'
        return 'C'
